#include "pari.h"
#include <stdio.h>
int main(){char *line=NULL;size_t cap=0;pari_init(512000000,500000);while(getline(&line,&cap,stdin)>0){pari_sp av=avma;GEN a=gp_read_str(line);long rows=itos(gel(a,1));setrand(gel(a,2));GEN src=gel(a,3),M=cgetg(lg(src),t_MAT);for(long i=1;i<lg(src);i++){GEN v=gel(src,i),w=cgetg(lg(v),t_VECSMALL);for(long j=1;j<lg(v);j++)w[j]=itos(gel(v,j));gel(M,i)=w;}GEN P=F2Ms_colelim(M,rows);GEN K=F2Ms_ker(M,rows);printf("OK [[");for(long i=1;i<lg(P);i++){if(i>1)printf(",");printf("%ld",P[i]);}printf("],[");for(long i=1;i<lg(K);i++){GEN v=gen_0;for(long j=lg(M)-1;j>0;j--){v=shifti(v,1);if(F2v_coeff(gel(K,i),j))v=addis(v,1);}if(i>1)printf(",");pari_printf("%Ps",v);}pari_printf("],%Ps]\n",getrand());set_avma(av);fflush(stdout);}pari_close();return 0;}